'use strict';
const icons={home:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1v15"/>',layers:'<path d="m12 3 10 5-10 5L2 8l10-5Zm-9 10 9 5 9-5M3 18l9 5 9-5"/>',pen:'<path d="m16 3 5 5L9 20l-6 1 1-6L16 3Zm-2 2 5 5"/>',paper:'<rect x="5" y="3" width="14" height="19" rx="2"/><path d="M9 7h6M9 12h6M9 17h3"/>',chart:'<path d="M3 3v18h18M7 15l4-4 4 2 5-7"/>',settings:'<path d="m10 3-1 3-3 1-3 3 2 3-1 4 4 1 2 3 4-1 3 1 2-4 3-2-1-4-3-1-1-3-4 1-3-1Z"/><circle cx="12" cy="12" r="3"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 18v3h16v-3"/>',check:'<path d="m5 12 4 4L20 5"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z"/>',shield:'<path d="m12 3 8 3v6c0 4-5 8-8 10-3-2-8-6-8-10V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',leaf:'<path d="M20 3C7 3 1 8 5 16c8 5 14-2 15-13ZM5 19 17 7"/>',flag:'<path d="M5 22V3c5-3 8 4 14 0v11c-6 4-9-3-14 0"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',folder:'<path d="M3 6V4h7l3 3h8v13H3V6Z"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M19 7a8 8 0 0 0-14 0M5 17a8 8 0 0 0 14 0"/>'};
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={boot:null,questions:[],docs:[],templates:[],session:null,index:0,drafts:{},spent:{},entered:0,saveChain:Promise.resolve(),saveTimer:null,bankFilter:{},diag:null,routeVersion:0};
const $=s=>document.querySelector(s);
const fmtDate=value=>value?new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'';
const pill=(text,tone='')=>`<span class="pill ${tone}">${E(text)}</span>`;
const btn=(text,action,kind='',ico='',attrs='')=>`<button class="btn ${kind}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${text}</button>`;
const empty=(title,description,action='')=>`<div class="empty"><div class="empty-symbol">${icon('leaf')}</div><strong>${title}</strong><p>${description}</p>${action}</div>`;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',6000)}
async function api(path,method='GET',data){const response=await fetch(path,{method,headers:{'Content-Type':'application/json'},...(data!==undefined?{body:JSON.stringify(data)}:{})});const value=await response.json();if(!response.ok)throw new Error(value.error||'请求失败');return value}
async function refresh(){S.boot=await api('/api/bootstrap')}
const routes=[['dashboard','学习概览','home'],['bank','我的题库','layers'],['knowledge','知识资料','book'],['practice','模块练习','pen'],['papers','模拟组卷','paper'],['profile','学习诊断','chart'],['coach','能力与训练','target'],['shenlun','申论专训','book'],['calculation','计算训练','clock'],['settings','模型与设置','settings']];
function shell(){const route=(location.hash.slice(1)||'dashboard').split('/')[0];const title=routes.find(r=>r[0]===route)?.[1]||(route==='session'?'作答空间':'作答复盘');$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#dashboard"><div class="brand-logo">${icon('book')}</div><div class="brand-copy"><div class="brand-name">知序</div><div class="brand-sub">LEARN WITH CLARITY</div></div></a><p class="nav-label">你的学习空间</p><nav class="nav">${routes.map(([id,label,ico],i)=>`${id==='settings'?'<div class="nav-sep"></div><p class="nav-label">工作台</p>':''}<a href="#${id}" aria-label="${label}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(ico)}<span>${label}</span></a>`).join('')}</nav><div class="side-foot"><div class="local-badge">${icon('shield')}<div>本地学习 · 自己掌握<br><span class="tiny muted">资料与记录保存在这台电脑</span></div></div><div class="user-box"><div class="avatar">学</div><div><div class="small">我的学习工作台</div><div class="tiny muted top12">一点一滴，学有所进</div></div></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">学习工作台 <span>/</span> <strong>${title}</strong></div><div class="row"><span class="tiny muted date-label">${new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'})}</span><span class="status-chip"><span class="dot"></span>本地运行中</span></div></header><main class="main" id="main"></main></div></div>`}
const pageHead=(label,title,sub,actions='')=>`<div class="page-head"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${sub}</p></div><div class="row wrap">${actions}</div></div>`;
const foot=()=>`<div class="footnote"><span>知序 ZHIXU · 从一次作答，走向真正理解</span><span>本地存储 / 来源与历史记录可核对</span></div>`;
async function render(){const version=++S.routeVersion;clearInterval(S.timer);if(!S.boot)await refresh();shell();const main=$('#main');main.innerHTML='<div class="loading-note"><span class="busy"></span>正在准备学习空间</div>';const [page,id]= (location.hash.slice(1)||'dashboard').split('/');try{let html='';switch(page){case 'dashboard':await refresh();html=dashboard();break;case 'bank':S.questions=await api('/api/questions');html=bank();break;case 'knowledge':S.docs=await api('/api/documents');html=knowledge();break;case 'practice':await refresh();html=practice();break;case 'papers':await refresh();S.templates=await api('/api/templates');html=papers();break;case 'profile':await refresh();S.estimate=await api('/api/score-estimates');html=profile();break;case 'coach':html=await S.coachPage();break;case 'shenlun':html=await S.shenlunPage();break;case 'calculation':html=await S.calculationPage(id);break;case 'settings':html=settings();break;case 'session':if(S.loadedSessionId!==id){S.drafts={};S.loadedSessionId=id}S.session=await api('/api/sessions/'+id);if(S.session.status==='finished'){location.hash='result/'+id;return}S.index=Math.min(S.index,S.session.questions.length-1);S.entered=Date.now();S.lastPeriodicSave=Date.now();html=sessionPage();break;case 'result':S.session=await api('/api/sessions/'+id);html=resultPage();break;default:html=dashboard()}
if(version!==S.routeVersion)return;main.innerHTML=html+foot();if(page==='session'){startTimer();updateSave('已保存');}if(page==='bank')bindBankFilters();if(page==='calculation')S.calculationMount();}catch(e){if(version===S.routeVersion)main.innerHTML=`<div class="error-panel">${E(e.message)}<div class="top20"><a href="#dashboard">返回学习概览</a></div></div>`}}
function dashboard(){const p=S.boot.profile;const scored=p.modules.reduce((n,m)=>n+m.scored,0);const rate=scored?Math.round(p.correct*100/scored):null;return pageHead('YOUR LEARNING, IN FOCUS','每一份努力，都有迹可循','从一道题出发，找到具体卡点，让下一次作答更有把握。',btn('导入我的题库','import','', 'plus'))+`<section class="hero"><div class="hero-copy"><div class="eyebrow">KNOW YOUR GAPS. FIND YOUR WAY.</div><h2>把每一道题，<br>变成清晰的下一步。</h2><p>用你的资料和真实作答，建立属于自己的学习路径。</p><div class="row">${btn('开始一组练习','go-practice','primary','arrow')}${btn('了解学习流程','show-flow','soft')}</div></div><div class="hero-art" aria-hidden="true"><div class="art-orbit"></div><div class="art-orbit o2"></div><div class="art-orbit o3"></div><div class="art-center">${icon('book')}</div><div class="art-node n1">${icon('check')}</div><div class="art-node n2">${icon('spark')}</div><div class="art-node n3">${icon('pen')}</div><div class="art-node n4"></div></div></section><section class="grid four stats">${stat('累计作答',p.total_attempts,'题','每次真实作答，都是学习的证据','pen')}${stat('作答正确率',rate===null?'—':rate,rate===null?'暂无记录':'%','按已判分题目计算，含重复练习','target')}${stat('已导入题库',p.question_count,'题','你的题目，你的练习节奏','layers')}${stat('累计练习用时',p.study_minutes,'分钟','根据逐题记录汇总','clock')}</section><div class="dashboard-body"><div class="stack"><section class="card"><div class="card-head"><h2>今天，从这里开始</h2>${pill('按自己的节奏')}</div><div class="action-list">${actionCard('模块练习','专注一个模块，逐步补齐卡点','pen','go-practice')}${actionCard('抽题组卷','按模块配比，完成一次限时模考','paper','go-papers')}${actionCard('错题复测','换一道题，验证是否真的理解','refresh','wrong-practice')}${actionCard('知识资料','让讲解回到你熟悉的教材与笔记','book','go-knowledge')}</div><div class="section-note">${icon('shield')}练习可逐题解析，模考统一在交卷后分析。</div></section><section class="card"><div class="card-head"><h2>最近的学习记录</h2><a class="tiny" href="#profile">查看全部 →</a></div>${p.recent_sessions.length?recentTable(p.recent_sessions):empty('第一份记录，从下一次作答开始','完成练习后，这里会展示成绩、用时和复盘入口。')}</section></div><div class="stack"><section class="card"><div class="card-head"><h2>值得关注的知识点</h2>${pill('基于真实作答','green')}</div>${p.knowledge.length?p.knowledge.slice(0,4).map(weakRow).join(''):empty('先了解，再判断','尚无作答证据。完成一组练习后，<br>这里会逐渐呈现你的具体卡点。',btn('开始摸底练习','go-practice','soft sm','arrow'))}<div class="section-note">少量样本只作观察，不急于给能力下结论。</div></section><section class="card"><div class="card-head"><h2>准备好你的学习材料</h2>${icon('folder')}</div><p class="small muted">载入国考行测真题，也可导入自己的题库与知识资料。</p><div class="row top20">${btn('载入国考真题','load-demo','soft sm','plus')}${btn('导入资料','go-knowledge','sm')}</div><p class="field-note">保留原题来源与整理版本，首次下载后离线使用。</p></section>${p.active_sessions.length?`<section class="card"><h3>继续上次作答</h3>${p.active_sessions.map(s=>`<div class="row between top12"><span class="small">${E(s.title)}</span><a class="btn sm" href="#session/${s.id}">继续 →</a></div>`).join('')}</section>`:''}</div></div>`}
function stat(label,value,unit,note,ico){return `<div class="stat"><div class="stat-label">${label}<div class="stat-icon">${icon(ico)}</div></div><div class="stat-number">${value}<span>${unit}</span></div><div class="stat-foot">${note}</div></div>`}
function actionCard(title,desc,ico,action){return `<button class="action-card" data-action="${action}"><div class="action-icon">${icon(ico)}</div><div><h3>${title}</h3><p>${desc}</p></div></button>`}
function weakRow(p){return `<div class="weak-row"><div class="row between"><button data-action="topic" data-point="${E(p.name)}">${E(p.name)}</button><span class="small muted">${p.accuracy===null?'待评阅':p.accuracy+'%'}</span></div><div class="progress-line"><i style="width:${p.accuracy||0}%"></i></div><div class="row between top12"><span class="tiny muted">${p.total} 次作答 · ${p.wrong} 次错误</span><span class="tiny muted">${E(p.sample_note)}</span></div></div>`}
function recentTable(records){return `<table class="recent-table"><thead><tr><th>练习名称</th><th>完成时间</th><th>得分</th><th></th></tr></thead><tbody>${records.map(s=>`<tr><td>${E(s.title)}<div class="tiny muted top12">${s.kind==='exam'?'限时模考':'专项练习'}</div></td><td class="muted tiny">${fmtDate(s.finished_at)}</td><td>${s.score}<span class="tiny muted"> / ${s.max_score}</span>${s.pending_score?'<div class="tiny muted">含待评阅题</div>':''}</td><td><a href="#result/${s.id}">复盘 →</a></td></tr>`).join('')}</tbody></table>`}
function bank(){return pageHead('QUESTION LIBRARY','让题目，各归其位','导入、分类、核对，再把题目组织成适合你的练习。',btn('导入题库','import','primary','upload'))+`${S.nationalEntry?.()||''}<div class="intro-box row between wrap"><span>自动归类到模块、子题型与具体知识点；模型建议允许你随时修正。</span><span>${S.questions.length} 题 · ${S.questions.filter(q=>q.status==='review').length} 题待核对</span></div><div class="toolbar"><input id="bank-search" placeholder="搜索题干、知识点或来源" aria-label="搜索题库" value="${E(S.bankFilter.search||'')}"><select id="bank-module" aria-label="筛选模块"><option value="">全部模块</option>${S.boot.modules.map(m=>`<option ${m===S.bankFilter.module?'selected':''}>${E(m)}</option>`).join('')}</select><select id="bank-status" aria-label="筛选题目状态"><option value="">全部状态</option><option value="review" ${S.bankFilter.status==='review'?'selected':''}>待核对</option><option value="ready" ${S.bankFilter.status==='ready'?'selected':''}>可练习</option></select><div class="grow"></div>${btn('下载导入模板','download-template','sm','download')}${btn('载入国考真题','load-demo','soft sm')}</div><div id="question-results" class="question-list">${bankRows()}</div>`}
function bankRows(){
 const f=S.bankFilter;
 const qs=S.questions.filter(q=>(!f.module||q.module===f.module)&&(!f.status||q.status===f.status)&&(!f.search||[q.stem,q.source,...q.knowledge_points].join(' ').includes(f.search)));
 const pages=Math.max(1,Math.ceil(qs.length/30));S.bankPage=Math.min(S.bankPage||0,pages-1);
 const visible=qs.slice(S.bankPage*30,(S.bankPage+1)*30);S.visibleQuestions=visible;
 if(!visible.length)return empty('这里还没有符合条件的题目','载入国考行测真题，或导入自己的题库。',btn('载入国考真题','load-demo','soft','plus'));
 const controls=`<div class="row between wrap"><div class="row">${btn('选择当前页','select-page','sm')}${btn('批量修改分类','bulk-edit','soft sm','pen')}<span class="tiny muted" id="selection-count">已选 ${S.selectedQuestions?.size||0} 题</span></div><span class="tiny muted">共 ${qs.length} 题 · 第 ${S.bankPage+1} / ${pages} 页</span></div>`;
 return controls+visible.map(q=>`<article class="card question-item"><div class="row between"><div class="row meta"><label class="checkbox-label"><input type="checkbox" data-select-q="${q.id}" aria-label="选择题目 ${E(q.stem.slice(0,20))}" ${S.selectedQuestions?.has(q.id)?'checked':''}></label>${pill(q.module,'green')}${pill(q.subtype)}${pill(S.boot.types[q.type])}${q.status==='review'?pill('待核对','orange'):''}${q.classification_status==='suggested'?pill('分类建议','orange'):''}</div>${btn('核对 / 编辑分类','edit-question','sm','pen',`data-id="${q.id}"`)}</div><h3>${E(q.stem)}</h3><div class="row wrap">${q.knowledge_points.map(p=>pill(p)).join('')}</div>${q.issues.length?`<p class="small top12" style="color:var(--orange)">${E(q.issues.join('；'))}</p>`:''}<div class="source">来源：${E(q.source)} · 难度：${E(q.difficulty)} · ${E(q.classification_basis)}</div></article>`).join('')+`<div class="row between">${btn('上一页','bank-prev','sm','back',S.bankPage===0?'disabled':'')}${btn('下一页','bank-next','sm','arrow',S.bankPage>=pages-1?'disabled':'')}</div>`;
}
function bindBankFilters(){for(const [id,key]of [['bank-search','search'],['bank-module','module'],['bank-status','status']])$('#'+id)?.addEventListener('input',e=>{S.bankFilter[key]=e.target.value;S.bankPage=0;$('#question-results').innerHTML=bankRows()})}
function knowledge(){return pageHead('YOUR KNOWLEDGE, CONNECTED','讲解，有据可循','把教材和笔记带进来，让个人复盘关联到具体资料段落。',btn('导入知识资料','add-document','primary','plus'))+`<div class="intro-box">支持批量导入，单个文件最多 500 MB、每批最多 100 个。资料与题库可同时上传，请为每个文件选择用途；扫描 PDF 和图片已启用本地中文 OCR，自动逐页识别。</div><div class="grid two top20">${S.docs.length?S.docs.map(d=>`<article class="document"><div class="row between"><div class="row">${icon('book')}<h3>${E(d.title)}</h3></div>${btn('移除','delete-doc','sm danger','',`data-id="${d.id}"`)}</div><p class="tiny muted bottom16">${d.chunk_count} 个检索片段 · ${(d.char_count||d.text.length).toLocaleString()} 字符 · ${fmtDate(d.created_at)}</p>${d.ocr?.ocr_pages?`<p class="field-note">本地 OCR ${d.ocr.ocr_pages} 页${d.ocr.low_confidence_lines?' · '+d.ocr.low_confidence_lines+' 行待核对':''}</p>`:''}${d.ocr?.warnings?.length?`<p class="intake-error">${d.ocr.warnings.map(E).join('<br>')}</p>`:''}<div class="row wrap top12">${btn('阅读 / 检索全文','read-document','soft sm','',`data-doc="${d.id}"`)}${btn('逐页补识别 / 原图','doc-page-assist','sm','',`data-doc="${d.id}"`)}</div><pre>${E(d.text)}</pre>${d.char_count>d.text.length?'<p class="field-note">这里只预览前 1200 字符，全文已建立检索。</p>':''}</article>`).join(''):`<div class="card wide">${empty('你的知识资料库，等待第一份材料','可以直接粘贴笔记，也可以上传文档。<br>资料不足时，系统会明确标出依据缺失。',btn('添加第一份资料','add-document','soft','plus'))}</div>`}</div>`}
function moduleOptions(all='全部模块'){return `<option value="">${all}</option>${S.boot.modules.map(m=>`<option value="${E(m)}">${E(m)}（${S.boot.inventory[m]||0}题）</option>`).join('')}`}
function practice(){return pageHead('FOCUSED PRACTICE','一次，专注一个具体进步','自由选择模块与知识点，也可以从错题和已观察到的弱项开始。')+`<div class="paper-layout"><section class="card"><div class="card-head"><h2>设置这次练习</h2>${pill('可随时自动保存','green')}</div><form id="practice-form"><div class="form-grid"><div><label for="practice-module">选择模块</label><select name="module" id="practice-module">${moduleOptions()}</select></div><div><label for="practice-point">具体知识点</label><select name="knowledge" id="practice-point"><option value="">不限知识点</option>${S.boot.knowledge_points.map(p=>`<option>${E(p)}</option>`).join('')}</select></div><div><label for="practice-mode">抽题方式</label><select id="practice-mode" name="mode"><option value="random">随机抽题</option><option value="ordered">顺序练习</option><option value="wrong">当前错题</option><option value="weak">薄弱知识点优先</option></select></div><div><label for="practice-difficulty">难度</label><select name="difficulty" id="practice-difficulty"><option value="">不限难度</option><option>基础</option><option>中等</option><option>较难</option><option>未知</option></select></div><div><label for="practice-count">题量</label><input name="count" id="practice-count" type="number" min="1" max="200" value="5" required></div><div><label for="practice-minutes">时长（分钟）</label><input name="minutes" id="practice-minutes" type="number" min="1" max="300" value="15" required></div><div class="wide"><label for="practice-feedback">解析时机</label><select name="feedback" id="practice-feedback"><option value="end">整组提交后统一分析</option><option value="each">逐题核对答案与解析</option></select></div></div><div class="check-row"><label class="checkbox-label"><input type="checkbox" name="exclude_seen">仅抽取未做过的题目</label></div><div class="row between top28"><span class="tiny muted">库存不足时会提示，不自动补题。</span><button type="submit" class="btn primary">${icon('arrow')}开始练习</button></div></form></section><div class="stack"><section class="card"><div class="card-head"><h2>练习，如何帮助你</h2>${icon('leaf')}</div><div class="flow-list">${flowSteps()}</div></section><section class="card"><h3>尚未导入题库？</h3><p class="small muted top12">先用 ${Object.keys(S.boot.inventory).length?'载入国考真题，或导入自己的题目':'载入国考真题开始练习'}。</p><div class="top20">${btn('载入国考真题','load-demo','soft sm','plus')}</div></section></div></div>`}
function flowSteps(){return [['作答，留下关键思路','选答案，也可以记下算式、排除理由与不确定处。'],['定位，找到具体卡点','信息不足时先追问，不把猜测写成确定错因。'],['讲解，接着你的理解继续','围绕具体步骤，关联资料，修正理解。'],['复测，验证能否迁移','用未见过的同类题，检验是否真正学会。']].map(([h,p],i)=>`<div class="flow-step"><div class="flow-num">0${i+1}</div><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}
function papers(){return pageHead('BUILD YOUR NEXT CHALLENGE','把目标，组进一张试卷','按模块配置题量与分值，完成一次有明确规则的限时练习。')+`<div class="paper-layout"><section class="card"><div class="card-head"><h2>自定义组卷</h2>${pill('题目与评分规则保留快照','green')}</div><form id="paper-form"><div class="form-grid"><div class="wide"><label for="paper-title">试卷名称</label><input id="paper-title" name="title" value="我的公考模拟卷" maxlength="100" required></div><div><label for="paper-minutes">考试时长（分钟）</label><input id="paper-minutes" name="minutes" type="number" min="1" max="300" value="30" required></div><div><label for="paper-difficulty">难度筛选</label><select id="paper-difficulty" name="difficulty"><option value="">不限难度</option><option>基础</option><option>中等</option><option>较难</option></select></div><div><label for="paper-region">地区（可选）</label><input id="paper-region" name="region" placeholder="与题库中的地区完全匹配"></div><div><label for="paper-year">年份（可选）</label><input id="paper-year" name="year" placeholder="例如 2025"></div></div><table class="quota-table top20"><thead><tr><th>模块</th><th>抽取题量</th><th>每题分值</th><th>可用库存</th></tr></thead><tbody>${S.boot.modules.filter(m=>(S.boot.inventory[m]||0)>0).map(m=>`<tr><td>${E(m)}</td><td><input type="number" min="0" max="200" value="0" data-quota="${E(m)}" aria-label="${E(m)}题量"></td><td><input type="number" min="0.1" max="100" step="0.1" value="1" data-points="${E(m)}" aria-label="${E(m)}每题分值"></td><td>${S.boot.inventory[m]} 题</td></tr>`).join('')||'<tr><td colspan="4">请先导入题库。</td></tr>'}</tbody></table><div class="check-row"><label class="checkbox-label"><input name="exclude_seen" type="checkbox">排除已做题</label></div><div id="paper-preview" class="small muted"></div><div class="row wrap top28">${btn('检查组卷条件','preview-paper','','eye')}${btn('保存为模板','save-template','','plus')}<div class="grow"></div><button type="submit" class="btn primary">${icon('arrow')}生成并开始模考</button></div></form></section><div class="stack"><section class="card"><div class="card-head"><h2>我的组卷模板</h2>${icon('folder')}</div>${S.templates.length?S.templates.map(t=>`<div class="row between template-item"><div><h3 class="small">${E(t.title)}</h3><p class="tiny muted">${Object.values(t.quotas||{}).reduce((a,b)=>a+b,0)} 题 · ${t.minutes} 分钟</p></div>${btn('使用','use-template','sm','',`data-id="${t.id}"`)}</div>`).join(''):empty('还没有保存的模板','设置好模块配比后，即可保存并重复使用。')}</section><section class="card"><h3>计分方式，先说清楚</h3><p class="small muted top12">按你设置的模块分值计算模考成绩。未明确正式考试权重时，这只是自定义计分，不代表官方估分。</p><div class="intro-box orange top20">共用材料与小题保持关联。整组抽题与题量冲突时，需要先调整配置。</div></section></div></div>`}
function paperSpec(){const form=$('#paper-form');const data=Object.fromEntries(new FormData(form));const quotas={},module_points={};form.querySelectorAll('[data-quota]').forEach(el=>{if(+el.value>0)quotas[el.dataset.quota]=+el.value});form.querySelectorAll('[data-points]').forEach(el=>module_points[el.dataset.points]=+el.value);return {...data,quotas,module_points,exclude_seen:form.elements.exclude_seen.checked}}
function current(){return S.session.questions[S.index]}
function draft(q=current()){return S.drafts[q.id]||(S.drafts[q.id]={...(S.session.answers[q.id]||{value:['single','multiple','boolean'].includes(q.type)?[]:'',reason:'',guessed:false,hinted:false,flagged:false,duration_seconds:0,attachments:[]})})}
function checkpoint(){if(!S.session||S.session.status!=='active'||!S.entered)return;const q=current();const d=draft(q);d.duration_seconds=(d.duration_seconds||0)+(Date.now()-S.entered)/1000;S.entered=Date.now()}
function updateSave(text){const el=$('#save-state');if(el)el.textContent=text}
function saveAnswer(extra={}){if(S.session?.answers[current().id]?.checked&&!extra.check)return S.saveChain.catch(()=>{});checkpoint();const q=current(),body={...draft(q),...extra},sid=S.session.id;updateSave('正在保存…');S.saveChain=S.saveChain.catch(()=>{}).then(async()=>{const updated=await api(`/api/sessions/${sid}/answers/${q.id}`,'PUT',body);if(S.session?.id===sid)S.session=updated;updateSave('已自动保存');return updated}).catch(e=>{updateSave('保存失败，请重试');toast(e.message,true);throw e});return S.saveChain}
function scheduleSave(){updateSave('等待保存…');clearTimeout(S.saveTimer);S.saveTimer=setTimeout(()=>saveAnswer().catch(()=>{}),600)}
async function flush(){clearTimeout(S.saveTimer);if(S.session?.status==='active'&&location.hash.startsWith('#session/'))await saveAnswer();else await S.saveChain.catch(()=>{})}
function sessionPage(){const s=S.session,q=current(),d=draft(q),checked=!!s.answers[q.id]?.checked,reading=!!S.isReadingQuestion?.(q);return `<div class="session-top"><div><div class="eyebrow">${s.kind==='exam'?'FOCUSED EXAM':'YOUR PRACTICE'}</div><h2>${E(s.title)}</h2><p class="tiny muted top12">${s.kind==='exam'?'模考模式 · 交卷后统一分析':'练习模式 · '+(s.feedback==='each'?'可逐题核对':'整组提交后分析')}</p></div><div class="row"><span id="save-state" class="save-state">已保存</span><div class="timer" id="timer">--:--</div>${btn('交卷','submit-session','primary','check')}</div></div><div class="exam-layout ${reading?'stats-exam-layout':''}"><section class="card question-panel ${reading?'stats-question-panel':''}"><div class="row between"><div class="row wrap">${pill(q.module,'green')}${pill(S.boot.types[q.type])}${pill(q.difficulty)}</div><span class="tiny muted">第 ${S.index+1} / ${s.questions.length} 题 · ${S.shenlunQuestionLabel?.(q)??(q.points+' 分')}</span></div>${S.questionMaterial?.(q)??(q.material?`<div class="material top20">${E(q.material)}</div>`:'')}<div class="question-stem">${S.nationalStem?.(q)??E(S.questionStem?.(q)??q.reading_stem??q.stem)}</div>${S.questionVisual?.(q)||''}${S.shenlunQuestionTools?.(q)||''}${['single','multiple','boolean'].includes(q.type)?`<div class="options">${Object.entries(q.options).map(([key,value])=>`<button class="option ${(Array.isArray(d.value)?d.value:[]).includes(key)?'selected':''}" data-action="choose" aria-pressed="${(Array.isArray(d.value)?d.value:[]).includes(key)}" data-value="${E(key)}" ${checked?'disabled':''}><span class="option-key">${E(key)}</span><span>${S.nationalOption?.(q,key)??E(value)}</span></button>`).join('')}</div>`:`<label for="written-answer">你的答案</label><textarea id="written-answer" placeholder="${q.type==='fill'?'在这里填写答案':'在这里写下你的回答…'}" ${checked?'disabled':''}>${E(d.value)}</textarea>`}<div class="reason-box"><div class="row between bottom16"><label for="reason" style="margin:0">关键思路 <span class="tiny muted">选填，帮助定位具体卡点</span></label>${pill('只需关键一步')}</div><textarea id="reason" placeholder="例如：我先确定基期，再列出算式…… / 我排除这个选项，因为……" ${checked?'disabled':''}>${E(d.reason)}</textarea>${S.coachSteps?.(q,d,checked)||''}<div class="check-row"><label class="checkbox-label"><input type="checkbox" id="guessed" ${d.guessed?'checked':''} ${checked?'disabled':''}>不确定 / 有猜测</label><label class="checkbox-label"><input type="checkbox" id="hinted" ${d.hinted?'checked':''} ${checked?'disabled':''}>已使用外部提示</label><label class="checkbox-label"><input type="checkbox" id="flagged" ${d.flagged?'checked':''} ${checked?'disabled':''}>标记稍后检查</label></div><label class="attachment-label">${icon('upload')}附上草稿图片（可选）<input type="file" id="evidence-file" accept="image/png,image/jpeg,image/webp" ${checked?'disabled':''}></label>${(d.attachments||[]).map(a=>`<p class="tiny muted top12">${E(a.name)} · 已保存</p>`).join('')}</div>${checked?`<div class="intro-box top20"><strong>参考答案：${E(Array.isArray(q.answer)?q.answer.join('、'):q.answer)}</strong><div class="prose top12">${S.nationalExplanation?.(q)??E(q.explanation||'原题未提供解析。')}</div></div>`:''}<div class="session-footer">${btn('上一题','prev-question','','back',S.index===0?'disabled':'')}<div class="row">${s.kind==='practice'&&s.feedback==='each'&&!checked?btn('核对本题','check-question','soft','check'):''}${S.index===s.questions.length-1?btn('完成并交卷','submit-session','primary','check'):btn('下一题','next-question','primary','arrow')}</div></div>${reading?'</section></div>':''}</section><aside class="exam-side"><section class="card"><div class="card-head"><h3>答题卡</h3><span class="tiny muted">${s.questions.length} 题</span></div><div class="answer-index">${s.questions.map((q,i)=>{const a=S.drafts[q.id]||s.answers[q.id];const answered=a&&(Array.isArray(a.value)?a.value.length:!!String(a.value).trim());return `<button class="${i===S.index?'current ':''}${answered?'answered ':''}${a?.flagged?'flagged':''}" data-action="jump" data-index="${i}" aria-label="跳转第${i+1}题">${i+1}</button>`}).join('')}</div><p class="field-note top20">绿色表示已作答，角标表示待检查。</p><div class="intro-box top20">无需把整段思考都写下来。记下关键条件、算式或排除理由即可。</div><div class="top20">${btn('交卷并查看分析','submit-session','primary full','check')}</div></section></aside></div>`}
function repaintSession(){const y=window.scrollY;$('#main').innerHTML=sessionPage()+foot();startTimer();window.scrollTo(0,y)}
function startTimer(){clearInterval(S.timer);const update=()=>{const s=S.session;if(!s||s.status!=='active')return;const left=Math.max(0,Math.floor(s.started_at+s.duration_minutes*60-Date.now()/1000));const el=$('#timer');if(el){el.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;el.classList.toggle('urgent',left<60)}if(left===0&&!S.submitting)submitSession(true);else if(left>0&&Date.now()-(S.lastPeriodicSave||Date.now())>15000&&!S.session.answers[current().id]?.checked){S.lastPeriodicSave=Date.now();saveAnswer().catch(()=>{})}};update();S.timer=setInterval(update,1000)}
async function moveTo(index){await flush();S.index=index;S.entered=Date.now();repaintSession();window.scrollTo(0,0)}
async function submitSession(automatic=false){if(S.submitting)return;S.submitting=true;try{if(!automatic)await flush();else await S.saveChain.catch(()=>{});const result=await api('/api/sessions/'+S.session.id+'/submit','POST',{});S.session=result;clearInterval(S.timer);await refresh();location.hash='result/'+result.id;toast(automatic?'时间已到，已自动交卷':'作答已保存，可以开始复盘')}catch(e){toast(e.message,true);const result=await api('/api/sessions/'+S.session.id).catch(()=>null);if(result?.status==='finished'){S.session=result;location.hash='result/'+result.id}}finally{S.submitting=false}}
function resultPage(){const s=S.session,written=!!s.attempts?.length&&s.attempts.every(a=>['short','essay'].includes(a.question.type));if(s.status!=='finished')return `<div class="card">这次作答还未交卷。<a href="#session/${s.id}">继续作答 →</a></div>`;return pageHead('REFLECT & UNDERSTAND','一次作答，一份更具体的了解',`${E(s.title)} · ${fmtDate(s.finished_at)} · 成绩按本次组卷规则计算`,btn('继续练习','go-practice','primary','arrow'))+`${S.learningAnalysisEntry?.()||''}<div class="grid four stats">${written?stat('主观题作答','待评阅','','语义评改与模拟估分另列于报告','pen'):stat('本次已计分得分',s.score,'/ '+s.max_score,'自定义评分规则，不等于正式考试估分','target')}${written?stat('已保存回答',s.attempts.filter(a=>String(a.response.value||'').trim()).length,'题','保留原文、步骤与用时','check'):stat('客观判分答对',s.correct_count,'题',`${s.pending_score?'另有 '+s.pending_score+' 分主观题待评阅':'本卷无待评阅分值'}`,'check')}${stat('本次总用时',Math.round(s.actual_seconds/60*10)/10,'分钟','交卷前实际用时','clock')}${stat('作答题量',s.count,'题',s.independent?'本次记录为独立作答':'含已见题、猜测或提示后作答','pen')}</div><div class="analysis-layout"><section class="card"><div class="card-head"><h2>逐题复盘</h2>${pill('从具体证据出发','green')}</div>${s.attempts.map((a,i)=>`<article class="attempt-item"><div class="row between"><div class="row">${pill('第 '+(i+1)+' 题')}${pill(a.correct===true?'答对':a.correct===false?'答错 / 漏答':'主观题待评阅',a.correct===true?'green':'orange')}${pill(a.question.module)}</div>${btn('查看个性化分析','diagnose','sm','spark',`data-id="${a.id}"`)}</div><div class="top12">${S.nationalStem?.(a.question)??E(S.questionStem?.(a.question)??a.question.reading_stem??a.question.stem)}</div>${S.isReadingQuestion?.(a.question)?S.questionReviewReading(a.question):(S.questionVisual?.(a.question)||'')}<div class="question-preview-options">${Object.entries(a.question.options).map(([k,v])=>`<div>${E(k)}. ${S.nationalOption?.(a.question,k)??E(v)}</div>`).join('')}</div><p class="tiny muted">你的答案：${E(Array.isArray(a.response.value)?a.response.value.join('、'):a.response.value)||'未作答'}　<span>参考答案：${E(Array.isArray(a.question.answer)?a.question.answer.join('、'):a.question.answer)||'原题未提供'}</span></p>${a.response.reason?`<div class="evidence">你的关键思路：${E(a.response.reason)}</div>`:''}<details class="source-block"><summary>查看原题参考解析</summary><p>${S.nationalExplanation?.(a.question)??E(a.question.explanation||'原题未提供解析')}</p></details><div class="tiny muted">${Math.round(a.response.duration_seconds||0)} 秒 · ${a.independent?'独立作答':'含辅助或已见证据'} · 来源：${E(a.question.source)}</div></article>`).join('')}</section><aside class="stack"><section class="card"><h3>下一步，先补哪一处？</h3><p class="small muted top12">打开单题分析，补充关键思路或回答追问，让讲解落到具体步骤。</p><div class="top20">${btn('查看知识点画像','go-profile','soft full','chart')}</div></section><section class="card"><h3>关于主观题</h3><p class="small muted top12">主观题保留为待评阅。申论可进入“申论专训”确认分析，获取材料核对与模拟配点建议；不会自动混入正式模考成绩。</p></section></aside></div>`}
function profile(){const p=S.boot.profile,estimate=S.estimate;return pageHead('PERSONAL LEARNING INSIGHTS','看见问题，也看见下一步','从真实作答、具体思路与复测证据中，逐渐建立你的学习画像。')+`${S.learningAnalysisEntry?.()||''}<div class="grid four stats">${stat('作答记录',p.total_attempts,'次','每次独立事件只计一次','pen')}${stat('观察到的知识点',p.knowledge.length,'个','一个知识点可以关联多道题','layers')}${stat('错误或漏答',p.wrong,'次','不把所有错误都视为知识缺口','target')}${stat('累计学习',p.study_minutes,'分钟','以实际记录为准','clock')}</div><div class="dashboard-body"><div class="stack"><section class="card"><div class="card-head"><h2>具体知识点画像</h2>${pill('可查看个人专题讲解','green')}</div>${p.knowledge.length?p.knowledge.map(weakRow).join(''):empty('先收集证据，再展开分析','完成练习后，会出现知识点正确率、样本量与专题复盘。',btn('开始练习','go-practice','soft'))}</section><section class="card"><div class="card-head"><h2>最近的练习与模考</h2></div>${p.recent_sessions.length?recentTable(p.recent_sessions):empty('暂无已完成记录','作答后在这里查看历史与复盘。')}</section></div><div class="stack"><section class="card"><div class="card-head"><h2>近期模考表现参考</h2>${pill(estimate.available?'描述性区间':'数据不足','orange')}</div>${estimate.available?`<div class="result-score">${estimate.low}–${estimate.high}<small> / 100</small></div><p class="small muted top12">近期均值 ${estimate.mean}，来自 ${estimate.sample} 次同配置独立模考。</p><p class="field-note">${E(estimate.method)}</p>`:`<p class="small muted">${E(estimate.reason)}</p><div class="top20">${btn('配置一套模考','go-papers','soft full','paper')}</div>`}</section><section class="card"><h3>模块表现</h3>${p.modules.length?`<div class="overview-chart">${p.modules.map(m=>`<div class="chart-column"><span class="chart-value">${m.accuracy===null?'—':m.accuracy+'%'}</span><div class="chart-bar" style="height:${m.accuracy||0}%"></div><span>${E(m.name)}</span></div>`).join('')}</div>`:empty('尚无模块统计','完成作答后自动生成。')}<p class="field-note">模块正确率用于定位范围；具体错因仍需作答思路支持。</p></section></div></div>`}
function settings(){const cfg=S.boot.settings;return pageHead('MODEL & WORKSPACE','让模型，成为你的学习助教','模型按需接入；题库、作答与知识资料独立保存在本机。')+`<div class="stack"><section class="card setting-card"><div class="card-head"><h2>大模型连接</h2>${pill(cfg.last_test?.ok?'连接已验证':cfg.last_test?'连接未通过':cfg.model?'已保存配置':'尚未配置',cfg.last_test?.ok?'green':'orange')}</div><div class="settings-status">${icon('shield')}API Key 使用 Windows 账号加密保存，不返回页面、不写入普通日志。</div><form id="model-form"><div class="form-grid"><div class="wide"><label for="base-url">服务地址 · Base URL</label><input name="base_url" id="base-url" type="url" placeholder="https://服务地址/v1" value="${E(cfg.base_url)}"><p class="field-note">支持 OpenAI-compatible chat/completions。本机 Ollama 等服务可使用 HTTP，远程服务需 HTTPS。</p></div><div><label for="model-name">模型名称</label><input name="model" id="model-name" placeholder="填写服务商提供的模型名" value="${E(cfg.model)}"></div><div><label for="vision-model">视觉模型（选页识别 / 图形题）</label><input name="vision_model" id="vision-model" value="${E(cfg.vision_model||cfg.model||'')}" placeholder="例如 deepseek-flash"></div><div><label for="review-model">独立复核模型（可选）</label><input name="review_model" id="review-model" value="${E(cfg.review_model||'')}" placeholder="留空则使用同一模型复核"></div><div><label for="timeout">超时（秒）</label><input name="timeout" id="timeout" type="number" min="5" max="180" value="${cfg.timeout||60}"></div><div class="wide"><label for="api-key">API Key</label><input name="api_key" id="api-key" type="password" autocomplete="new-password" placeholder="${cfg.has_key?'已保存；留空则保留现有 Key':'本机无需密钥的模型可留空'}"><p class="field-note">需要兼容 JSON 结构化输出。草稿图片分析还需模型具备视觉能力；调用可能产生服务商费用。</p></div></div><div class="row top28 wrap"><button type="submit" class="btn primary">保存配置</button>${btn('测试连接','test-model','','spark')}${btn('清除已保存 Key','clear-key','danger sm')}</div><div id="model-test-result" class="field-note">${E(cfg.last_test?.message||'')}</div></form></section><section class="card setting-card export-note"><div><h2>备份学习数据</h2><p class="small muted top12">导出题库、知识资料、作答、诊断与套卷记录。模型凭据不包含在内。</p><p class="field-note">完整恢复请备份项目的 data 文件夹。JSON 导出用于查看和迁移。</p></div>${btn('导出 JSON 备份','export','','download')}</section><section class="card setting-card"><h2>运行与数据位置</h2><p class="small muted top12">本地地址：${E(location.origin)}<br>项目位置：当前解压目录<br>数据文件：项目目录下 data/study.sqlite3<br>版本：0.11.0 · 本地个人使用版</p><p class="field-note">未连接模型时可正常导入、练习、组卷与计分。个性化语义分析需要实际连接模型；本地分析只陈述可观察事实。</p></section></div>`}
function openModal(title,html){$('#modal-root').innerHTML=`<div class="modal-backdrop" data-backdrop="true"><section class="modal" role="dialog" aria-modal="true" aria-label="${E(title)}"><div class="modal-head"><h2>${E(title)}</h2><button data-action="close-modal" aria-label="关闭">×</button></div><div id="modal-body">${html}</div></section></div>`;S.focusBeforeModal=document.activeElement;$('.modal input,.modal textarea,.modal button')?.focus()}
function closeModal(){$('#modal-root').innerHTML='';S.focusBeforeModal?.focus?.()}
function busyModal(message){$('#modal-body').innerHTML=`<div class="loading-note"><span class="busy"></span>${E(message)}</div>`}
function openImport(){S.importFile=null;S.importBatch=null;openModal('导入题库',`<div class="intro-box bottom16">先预览提取与分类结果，再确认入库。不会自动把缺少答案的题目放入模考。</div><label class="import-zone">${icon('upload')}<strong id="import-file-label">选择你的题库文件</strong><p>JSON / JSONL / CSV / XLSX / TXT / Markdown / DOCX / 文字版 PDF · 最大 15 MB</p><input type="file" id="import-file" accept=".json,.jsonl,.csv,.tsv,.xlsx,.txt,.md,.docx,.pdf"></label><div class="top20"><label for="import-text">或直接粘贴题目文本 / JSON 数组</label><textarea id="import-text" placeholder="1. 题干……&#10;A. 选项一&#10;B. 选项二&#10;答案：A&#10;解析：……"></textarea></div><div class="check-row"><label class="checkbox-label"><input type="checkbox" id="import-ai">使用已配置模型辅助提取 / 分类（会发送题目内容）</label></div><div class="row between">${btn('下载导入模板','download-template','sm','download')}${btn('提取并预览分类','preview-import','primary','arrow')}</div><div id="import-error" class="inline-error"></div>`)}
async function filePayload(file){if(file.size>15*1024*1024)throw new Error('文件超过15 MB，请拆分后导入。');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,data:reader.result.split(',')[1]});reader.onerror=()=>reject(new Error('文件读取失败'));reader.readAsDataURL(file)})}
async function previewImport(){const use_ai=$('#import-ai').checked;let data;if(S.importFile)data=await filePayload(S.importFile);else{const text=$('#import-text').value.trim();if(!text)throw new Error('请选择文件或粘贴题目。');if(text.startsWith('[')||text.startsWith('{')){const parsed=JSON.parse(text);data={rows:Array.isArray(parsed)?parsed:parsed.questions||[parsed],name:'手动 JSON 导入'}}else data={text,name:'粘贴题目'}}busyModal('正在提取与分类，模型辅助可能需要一些时间…');try{S.importBatch=await api('/api/imports/preview','POST',{...data,use_ai});showImportPreview()}catch(e){openImport();$('#import-error').textContent=e.message}}
function showImportPreview(){const b=S.importBatch;$('#modal-body').innerHTML=`<div class="row between bottom16"><span class="small">${E(b.name)}</span>${pill(b.total+' 题已提取','green')}</div><div class="intro-box">${b.items.filter(q=>q.status==='review').length} 题需核对 · ${b.items.filter(q=>q.duplicate_of).length} 题重复。入库后可逐题修正分类、知识点与答案。</div><div class="import-preview">${b.items.map((q,i)=>`<div class="preview-row"><div class="row wrap">${pill(i+1)}${pill(q.module,'green')}${pill(q.subtype)}${q.duplicate_of?pill('重复，跳过','orange'):''}${q.status==='review'?pill(q.issues.join('；'),'orange'):''}</div><p>${E(q.stem)}</p><p class="tiny muted">${E(q.knowledge_points.join(' / ')||'知识点待确认')}</p></div>`).join('')||'<p class="note-empty">没有提取到完整题目。请按模板整理，或配置模型后使用辅助提取。</p>'}${b.errors.map(e=>`<p class="inline-error">第 ${e.row} 行：${E(e.message)}</p>`).join('')}</div>${b.extracted_text?`<details class="source-block"><summary>查看提取原文</summary><p>${E(b.extracted_text)}</p></details>`:''}<div class="row between">${btn('重新选择','import','sm')}${btn('确认入库','commit-import','primary','check',b.total?'':'disabled')}</div>`}
function editQuestion(id){const q=S.questions.find(q=>q.id===id);S.editId=id;openModal('核对题目与分类',`<p class="small bottom16">${E(q.stem)}</p>${q.rich_content?S.nationalReview?.(q):S.isReadingQuestion?.(q)?S.questionReviewReading(q):(S.questionVisual?.(q)||'')}${q.material?`<div class="material bottom16">${E(q.material)}</div>`:''}<form id="question-form"><div class="form-grid"><div><label for="edit-module">模块</label><select id="edit-module" name="module">${S.boot.modules.map(m=>`<option ${m===q.module?'selected':''}>${E(m)}</option>`).join('')}</select></div><div><label for="edit-subtype">子题型</label><input id="edit-subtype" name="subtype" value="${E(q.subtype)}"></div><div class="wide"><label for="edit-points">具体知识点（用逗号分隔）</label><input id="edit-points" name="knowledge_points" value="${E(q.knowledge_points.join('，'))}"></div><div><label for="edit-answer">参考答案</label><input id="edit-answer" name="answer" value="${E(Array.isArray(q.answer)?q.answer.join(','):q.answer)}"><p class="field-note">选择题填写选项字母；填空多个等价答案用 | 分隔。</p></div><div><label for="edit-difficulty">难度标签</label><select id="edit-difficulty" name="difficulty">${['未知','基础','中等','较难'].map(x=>`<option ${x===q.difficulty?'selected':''}>${x}</option>`).join('')}</select></div></div>${q.issues.length?`<div class="intro-box orange top20">${E(q.issues.join('；'))}。缺图或题面不完整时，请修正原文件后重新导入。</div>`:''}<div class="question-preview-options top20">${Object.entries(q.options).map(([k,v])=>`<div>${E(k)}. ${S.nationalOption?.(q,k)??E(v)}</div>`).join('')}</div><p class="field-note">${E(q.explanation)}</p><div class="top20"><button class="btn primary" type="submit">确认并保存</button></div></form>`)}
function addDocument(){S.docFile=null;openModal('添加知识资料',`<form id="document-form"><div><label for="doc-title">资料名称</label><input id="doc-title" name="title" placeholder="例如：资料分析 · 基础方法笔记"></div><label class="import-zone top20">${icon('upload')}<strong id="doc-file-label">选择知识文档</strong><p>TXT / Markdown / DOCX / 文字版 PDF</p><input type="file" id="doc-file" accept=".txt,.md,.docx,.pdf"></label><div class="top20"><label for="doc-text">或粘贴知识笔记正文</label><textarea id="doc-text" name="text" placeholder="在这里粘贴方法、概念或学习笔记…"></textarea></div><div class="row top20"><button type="submit" class="btn primary">导入知识资料</button></div></form>`)}
async function diagnose(id,useAI=false,response=''){S.attemptId=id;openModal('个性化作答分析','<div class="loading-note"><span class="busy"></span>正在对照作答与知识资料…</div>');try{S.diag=await api('/api/diagnoses','POST',{attempt_id:id,use_ai:useAI,response});showDiagnosis()}catch(e){$('#modal-body').innerHTML=`<div class="error-panel">${E(e.message)}</div><div class="top20">${btn('查看本地证据分析','diagnose-local','soft')}</div>`}}
function showDiagnosis(){const d=S.diag;const visualQuestion=d.display_question||S.session?.questions?.find(q=>q.id===d.question_id)||S.session?.attempts?.find(a=>a.id===d.attempt_id)?.question;$('#modal-body').innerHTML=`${visualQuestion?.rich_content?S.nationalReview?.(visualQuestion):visualQuestion?(S.isReadingQuestion?.(visualQuestion)?S.questionReviewReading(visualQuestion):(S.questionVisual?.(visualQuestion)||'')):''}<div class="row between wrap bottom16"><div class="row wrap">${pill(d.engine==='model'?'大模型个性化分析':'本地证据整理','green')}${pill(d.confidence,'orange')}${d.reviewed?pill('已独立复核','green'):''}</div>${d.engine!=='model'?btn('使用模型深入分析','diagnose-ai','soft sm','spark'):''}</div><div class="intro-box">${E(d.cause)}</div>${d.review_note?`<p class="field-note">${E(d.review_note)}</p>`:''}<div class="diagnosis-section"><h3>真实作答证据</h3>${d.observations.map(o=>`<p class="small muted">${E(o)}</p>`).join('')}</div><div class="diagnosis-section"><h3>针对性讲解</h3><div class="prose">${E(d.explanation)}</div></div>${d.reference_score!==undefined?`<div class="intro-box orange">AI 参考分：${d.reference_score} 分<br>${E(d.score_reason)}<br>此参考分不自动计入模考成绩。</div>`:''}${d.questions.length?`<div class="diagnosis-section"><h3>再补充一个关键步骤</h3>${d.questions.map(q=>`<p class="small">${E(q)}</p>`).join('')}<textarea id="followup" class="top12" placeholder="写下你的具体步骤或疑惑…"></textarea><div class="top12">${btn(d.engine==='model'?'提交并更新分析':'保存补充思路','answer-followup','primary sm','arrow')}</div></div>`:''}${d.dialogue.map(x=>`<div class="dialogue"><strong>你的补充：</strong>${E(x.text)}</div>`).join('')}<div class="diagnosis-section"><h3>下一步如何验证</h3><p class="small">${E(d.next_action)}</p><div class="row wrap top12">${d.knowledge_points.map(p=>btn('复测：'+E(p),'retest','sm','refresh',`data-point="${E(p)}"`)).join('')}</div></div><div class="diagnosis-section"><h3>相关知识资料</h3>${sourceBlocks(d.sources)}</div><div class="feedback-row">${btn('这个讲解有帮助','feedback-help','soft sm','check')}${btn('仍未理解','feedback-no','sm')}</div><p class="field-note">${E(d.feedback||'你的反馈将与本次诊断一同保留，后续分析可读取。')}</p>`}
function sourceBlocks(sources){return sources.length?sources.map(s=>`<details class="source-block"><summary>${E(s.title)} · ${E(s.page||'片段 '+s.chunk_id)}</summary><p>${E(s.text)}</p></details>`).join(''):'<p class="small muted">尚未找到关联资料。可在“知识资料”中补充教材或笔记；此处不会生成虚构出处。</p>'}
async function topic(point,useAI=false){S.topic=point;openModal('个人专题 · '+point,'<div class="loading-note"><span class="busy"></span>正在汇总相关作答证据…</div>');try{const d=await api('/api/explanations','POST',{point,use_ai:useAI});$('#modal-body').innerHTML=`<div class="row between bottom16">${pill(d.sample+' 次作答 / '+d.wrong+' 次错误','green')}${useAI?'':btn('整合此知识点（API）','topic-ai','soft sm','spark')}</div><div class="prose">${E(d.explanation)}</div><div class="diagnosis-section"><h3>关联的个人思路</h3>${d.attempts.map(a=>`<div class="evidence"><p>${E(a.stem)}</p><p class="muted">${a.reason?'你的思路：'+E(a.reason):'未记录关键思路，具体错因仍待确认。'}</p>${btn('查看单题分析','diagnose','sm','',`data-id="${a.id}"`)}</div>`).join('')}</div><div class="diagnosis-section"><h3>知识资料依据</h3>${sourceBlocks(d.sources)}</div>${btn('抽取未见题复测','retest','primary','refresh',`data-point="${E(point)}"`)}`}catch(e){$('#modal-body').innerHTML=`<div class="error-panel">${E(e.message)}</div>`}}
function download(name,content,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
const actions={
 'select-page':()=>{S.selectedQuestions??=new Set();S.visibleQuestions.forEach(q=>S.selectedQuestions.add(q.id));$('#question-results').innerHTML=bankRows()},
 'bank-prev':()=>{S.bankPage--;$('#question-results').innerHTML=bankRows();window.scrollTo(0,0)},
 'bank-next':()=>{S.bankPage++;$('#question-results').innerHTML=bankRows();window.scrollTo(0,0)},
 'bulk-edit':()=>{if(!S.selectedQuestions?.size)throw new Error('请先选择需要批量修改的题目');openModal('批量修改分类',`<p class="small muted">将修改已选 ${S.selectedQuestions.size} 道题，保留原分类历史。</p><form id="bulk-form" class="top20"><div class="form-grid"><div><label for="bulk-module">目标模块</label><select id="bulk-module" name="module">${moduleOptions('请选择模块')}</select></div><div><label for="bulk-subtype">子题型（选填）</label><input id="bulk-subtype" name="subtype" placeholder="留空则保留原值"></div><div class="wide"><label for="bulk-points">知识点（选填，逗号分隔）</label><input id="bulk-points" name="knowledge_points" placeholder="留空保留原知识点；填写则替换"></div></div><button class="btn primary top20" type="submit">确认批量修改</button></form>`)},
 'go-practice':()=>location.hash='practice','go-papers':()=>location.hash='papers','go-knowledge':()=>location.hash='knowledge','go-profile':()=>location.hash='profile',
 'import':openImport,'close-modal':closeModal,'preview-import':previewImport,
 'commit-import':async()=>{const b=await api('/api/imports/'+S.importBatch.id+'/commit','POST',{});closeModal();await refresh();toast(`已导入 ${b.added} 题，跳过 ${b.skipped} 道重复题`);location.hash='bank';await render()},
 'load-demo':()=>actions['national-open'](),
 'show-flow':()=>openModal('从一次作答，走向真正理解',`<div class="flow-list">${flowSteps()}</div><div class="intro-box top28">接入模型后，可对具体思路进行语义分析。模型未配置时，仍可做题、组卷与核对参考解析。</div>`),
 'wrong-practice':async()=>{location.hash='practice';await render();$('#practice-mode').value='wrong'},
 'edit-question':el=>editQuestion(el.dataset.id),'add-document':addDocument,
 'delete-doc':async el=>{const d=S.docs.find(d=>d.id===el.dataset.id);openModal('移除知识资料',`<p>将移除“${E(d.title)}”的本地检索资料。已保存诊断中的引用快照仍保留。</p><div class="row top20">${btn('取消','close-modal')}${btn('确认移除','confirm-delete-doc','danger','',`data-id="${d.id}"`)}</div>`)},
 'confirm-delete-doc':async el=>{await api('/api/documents/'+el.dataset.id,'DELETE');closeModal();await refresh();await render()},
 'download-template':()=>{download('题库导入模板.json',JSON.stringify([{stem:'只有完成报名，才能参加考试。小李参加了考试，可以推出什么？',type:'single',options:{A:'小李完成了报名',B:'报名者都参加了考试',C:'小李没有报名',D:'无法判断'},answer:['A'],explanation:'只有A才B表示B→A。参加考试可推出已经完成报名。',module:'判断推理',subtype:'逻辑判断',knowledge_points:['充分条件与必要条件'],difficulty:'基础',points:1,material:'',group_id:'',whole_group:false}],null,2))},
 'preview-paper':async()=>{const data=paperSpec();if(!Object.keys(data.quotas).length)throw new Error('请设置至少一个模块的抽题数量');const r=await api('/api/papers/preview','POST',data);$('#paper-preview').textContent=`条件可满足：${r.count} 题 / 满分 ${r.max_score} 分 · ${Object.entries(r.distribution).map(([m,n])=>`${m} ${n} 题`).join('，')}`},
 'save-template':async()=>{const data=paperSpec();if(!Object.keys(data.quotas).length)throw new Error('请先设置模块题量');await api('/api/templates','POST',data);toast('组卷模板已保存');await render()},
 'use-template':el=>{const t=S.templates.find(t=>t.id===el.dataset.id);const form=$('#paper-form');for(const key of ['title','minutes','difficulty','region','year'])if(form.elements[key])form.elements[key].value=t[key]||'';form.elements.exclude_seen.checked=t.exclude_seen||false;form.querySelectorAll('[data-quota]').forEach(i=>i.value=t.quotas[i.dataset.quota]||0);form.querySelectorAll('[data-points]').forEach(i=>i.value=t.module_points[i.dataset.points]||1);toast('已应用模板，可检查后开始')},
 'choose':el=>{const q=current(),d=draft(q),v=el.dataset.value;d.value=q.type==='multiple'?(d.value.includes(v)?d.value.filter(x=>x!==v):[...d.value,v]):[v];repaintSession();scheduleSave()},
 'prev-question':()=>moveTo(S.index-1),'next-question':()=>moveTo(S.index+1),'jump':el=>moveTo(+el.dataset.index),
 'submit-session':()=>{openModal('提交本次作答',`<p>交卷后将保存本次成绩、作答与关键思路，并开放逐题复盘。</p><p class="small muted top12">未作答的客观题按未得分记录，主观题保留待评阅。</p><div class="row top20">${btn('继续作答','close-modal')}${btn('确认交卷','confirm-submit','primary','check')}</div>`)},
 'confirm-submit':async()=>{closeModal();await submitSession()},
 'check-question':async()=>{await saveAnswer({check:true});draft().checked=true;repaintSession();toast('已展示答案，本次记录为辅助练习')},
 'diagnose':el=>diagnose(el.dataset.id),'diagnose-ai':()=>diagnose(S.attemptId,true),'diagnose-local':()=>diagnose(S.attemptId,false),
 'answer-followup':async()=>{const response=$('#followup').value.trim();if(!response)throw new Error('请先写下关键步骤或疑惑');await diagnose(S.attemptId,S.diag.engine==='model',response)},
 'feedback-help':async()=>{S.diag=await api('/api/diagnoses/'+S.diag.id+'/feedback','POST',{feedback:'用户反馈：这次讲解有帮助。'});showDiagnosis();toast('已记录本次讲解反馈')},
 'feedback-no':()=>{openModal('哪里仍然不清楚？',`<p class="small muted">指出具体步骤或希望换一种讲法，后续分析会读取这条反馈。</p><textarea id="teaching-feedback" class="top20" placeholder="例如：公式我理解了，但仍不知道怎么从题干确定基期。"></textarea><div class="top20">${btn('保存反馈','save-feedback','primary')}</div>`)},
 'save-feedback':async()=>{const text=$('#teaching-feedback').value.trim();if(!text)throw new Error('请填写具体疑惑');S.diag=await api('/api/diagnoses/'+S.diag.id+'/feedback','POST',{feedback:'用户反馈：仍未理解。'+text});openModal('个性化作答分析','');showDiagnosis()},
 'topic':el=>topic(el.dataset.point),'topic-ai':()=>topic(S.topic,true),
 'retest':async el=>{const result=await api('/api/retests','POST',{point:el.dataset.point,count:2});closeModal();S.index=0;S.drafts={};location.hash='session/'+result.id},
 'test-model':async()=>{const form=$('#model-form');const data=Object.fromEntries(new FormData(form));await api('/api/settings','POST',data);form.elements.api_key.value='';$('#model-test-result').textContent='正在测试连接与 JSON 输出…';try{const result=await api('/api/settings/test','POST',{});$('#model-test-result').textContent=result.message;await refresh();toast(result.message)}catch(e){$('#model-test-result').textContent=e.message;throw e}},
 'clear-key':async()=>{await api('/api/settings','POST',{...S.boot.settings,clear_key:true});await refresh();toast('本机保存的 API Key 已清除');await render()},
 'export':async()=>download('知序-学习备份-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(await api('/api/export'),null,2))
};
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;const fn=actions[el.dataset.action];if(!fn)return;event.preventDefault();if(el.disabled)return;el.disabled=true;try{await fn(el)}catch(e){toast(e.message,true)}finally{el.disabled=false}});
document.addEventListener('input',event=>{const el=event.target;if(['reason','written-answer','guessed','hinted','flagged'].includes(el.id)&&S.session){const d=draft();if(el.id==='reason')d.reason=el.value;else if(el.id==='written-answer')d.value=el.value;else d[el.id]=el.checked;scheduleSave()}});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.dataset.selectQ){S.selectedQuestions??=new Set();el.checked?S.selectedQuestions.add(el.dataset.selectQ):S.selectedQuestions.delete(el.dataset.selectQ);$('#selection-count').textContent='已选 '+S.selectedQuestions.size+' 题'}if(el.id==='import-file'){S.importFile=el.files[0];$('#import-file-label').textContent=S.importFile?.name||'选择题库文件'}if(el.id==='doc-file'){S.docFile=el.files[0];$('#doc-file-label').textContent=S.docFile?.name||'选择知识文档'}if(el.id==='evidence-file'&&el.files[0]){const file=el.files[0];if(file.size>3*1024*1024)throw new Error('草稿图片最多 3 MB');const result=await api('/api/evidence','POST',await filePayload(file));draft().attachments=[...(draft().attachments||[]),result].slice(0,3);await saveAnswer();repaintSession();toast('草稿已保存在本机；语义分析需视觉模型')}}catch(e){toast(e.message,true)}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;const button=form.querySelector('[type=submit]');if(button)button.disabled=true;try{const data=Object.fromEntries(new FormData(form));switch(form.id){case 'bulk-form':{if(!data.module)throw new Error('请选择目标模块');await api('/api/questions/bulk','PATCH',{ids:[...S.selectedQuestions],module:data.module,subtype:data.subtype,...(data.knowledge_points.trim()?{knowledge_points:data.knowledge_points.split(/[,，;；]/).map(x=>x.trim()).filter(Boolean)}:{})});S.selectedQuestions.clear();closeModal();await refresh();await render();toast('批量分类已保存');break}case 'practice-form':{const s=await api('/api/practice-sessions','POST',{...data,exclude_seen:form.elements.exclude_seen.checked,title:(data.module||'综合')+' · '+(data.mode==='wrong'?'错题复习':'专项练习')});S.index=0;S.drafts={};location.hash='session/'+s.id;break}case 'paper-form':{const spec=paperSpec();if(!Object.keys(spec.quotas).length)throw new Error('请至少配置一个模块题量');const s=await api('/api/exam-sessions','POST',spec);S.index=0;S.drafts={};location.hash='session/'+s.id;break}case 'question-form':await api('/api/questions/'+S.editId,'PATCH',{...data,knowledge_points:data.knowledge_points.split(/[,，;；]/).map(x=>x.trim()).filter(Boolean)});closeModal();await refresh();await render();toast('题目核对与分类已保存');break;case 'document-form':{let payload={title:data.title,text:data.text};if(S.docFile)payload={...await filePayload(S.docFile),title:data.title};await api('/api/documents','POST',payload);closeModal();await refresh();location.hash='knowledge';await render();toast('知识资料已导入');break}case 'model-form':await api('/api/settings','POST',data);form.elements.api_key.value='';await refresh();toast('模型配置已加密保存');await render();break}}catch(e){toast(e.message,true)}finally{if(button)button.disabled=false}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();if(event.key==='Tab'&&$('.modal')){const items=[...$('.modal').querySelectorAll('button:not([disabled]),input:not([type=hidden]),textarea,select,a[href]')].filter(el=>el.offsetParent!==null);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',async event=>{clearTimeout(S.saveTimer);if(event.oldURL.includes('#session/')&&S.session?.status==='active'){try{await saveAnswer()}catch(e){toast(e.message,true)}}await S.saveChain.catch(()=>{});await render()});
window.addEventListener('beforeunload',event=>{if(['正在保存…','等待保存…'].includes($('#save-state')?.textContent)){event.preventDefault();event.returnValue=''}});
if(document.readyState==='complete')render();else document.addEventListener('DOMContentLoaded',()=>render(),{once:true});
